def count_words(text):
    """סופר מילים בטקסט - משלב split (מודול 4) ו-len"""
    words = text.strip().split()  # פיצול לרשימה (מודול 3)
    return len(words)

def reverse_words(text):
    """הופך סדר מילים - משלב split, reverse, join"""
    words = text.split()          # מחרוזת → רשימה
    words.reverse()               # היפוך במקום (מודול 3)
    return ' '.join(words)        # רשימה → מחרוזת

def word_frequency(text):
    """סופר תדירות מילים - משלב מילון (מודול 5)"""
    words = text.lower().split()
    freq = {}  # מילון ריק
    for word in words:  # לולאה (מודול 2)
        if word in freq:
            freq[word] += 1
        else:
            freq[word] = 1
    return freq

# בדיקות
text = 'שלום עולם שלום'
print(count_words(text))       # 3
print(reverse_words(text))     # 'שלום עולם שלום'
print(word_frequency(text))    # {'שלום': 2, 'עולם': 1}

