def create_gradebook():
    """
    מערכת ציונים - משלב מילונים, רשימות, לולאות
    """
    # מילון: שם → רשימת ציונים
    gradebook = {
        'דני': [85, 90, 78],
        'רונית': [92, 88, 95],
        'יוסי': [70, 75, 80]
    }
    return gradebook

def calculate_average(grades):
    """חישוב ממוצע רשימה (מודול 3)"""
    return sum(grades) / len(grades)

def get_all_averages(gradebook):
    """ממוצע לכל סטודנט - מחזיר מילון חדש"""
    averages = {}  # מילון ריק
    for name, grades in gradebook.items():  # items() (מודול 5)
        averages[name] = round(calculate_average(grades), 2)
    return averages

def get_top_students(gradebook, threshold=85):
    """מחזיר רשימת סטודנטים עם ממוצע מעל הסף"""
    top = []  # רשימה ריקה (מודול 3)
    for name, grades in gradebook.items():
        if calculate_average(grades) >= threshold:  # תנאי (מודול 1)
            top.append(name)
    return top

# הרצה
gb = create_gradebook()
print('ממוצעים:', get_all_averages(gb))
print('מצטיינים:', get_top_students(gb))

